// CreateContext creates a new context with a default configuration
// Empty monitors, empty GitLab URL, other values default. The file carries the
// commented price example and is never overwritten.
func CreateContext(contextName string) error {
	if err := ValidateNewContextName(contextName); err != nil {
		return err
	}
	path, err := GetContextPath(contextName)
	if err != nil {
		return err
	}
	err = createContextFile(path, newContextConfig())
	if errors.Is(err, os.ErrExist) {
		return fmt.Errorf("context '%s' already exists: %w", contextName, ErrContextExists)
	}
	return err
}

// WriteNewContext writes cfg as the context contextName, with the commented
// price example, replacing any file already there.
func WriteNewContext(cfg *Config, contextName string) error {
	if err := ValidateContextName(contextName); err != nil {
		return err
	}
	path, err := GetContextPath(contextName)
	if err != nil {
		return err
	}
	data, err := marshalContext(cfg, true)
	if err != nil {
		return err
	}
	if err := EnsureConfigDir(); err != nil {
		return err
	}
	return os.WriteFile(path, data, 0600)
}

// CreateDefaultContextIfMissing creates config.yaml when the current context is
// "default" and the file is absent, and reports whether it did. An existing
// config.yaml, even an invalid one, is neither read nor rewritten. The
// creation is exclusive, so of several concurrent callers only one gets true.
func CreateDefaultContextIfMissing() (bool, error) {
	if CurrentContextName() != "default" {
		return false, nil
	}
	path, err := GetContextPath("default")
	if err != nil {
		return false, err
	}
	err = createContextFile(path, newContextConfig())
	switch {
	case err == nil:
		return true, nil
	case errors.Is(err, os.ErrExist):
		return false, nil
	default:
		return false, err
	}
}
// disagree about which file is scanned with. Resolving it here settles it
// against DevDesk's own working directory, once, at load: the path that gets
// mounted and the path the configuration view shows are then the same string.
//
// A path that cannot be resolved is left as it was rather than dropped:
// RunGitleaks refuses an unreadable config with the reason, and that is a
// better place to fail than a config file that silently loses a setting.
func absolute(path string) string {
	if path == "" {
		return ""
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return path
	}
	return abs
}

// SaveContext saves the configuration to a specific context file
func SaveContext(cfg *Config, contextName string) error {
	if err := ValidateContextName(contextName); err != nil {
		return err
	}

	configPath, err := GetContextPath(contextName)
	if err != nil {
		return err
	}

	// Ensure the directory exists
	if err := EnsureConfigDir(); err != nil {
		return err
	}

	// Keep the commented price example only when the file already carries it
	// and no price is set; a missing file never gets the block.
	withExample := false
	if len(cfg.AgentUsage.Prices) == 0 {
		existing, readErr := os.ReadFile(configPath)
		switch {
		case readErr == nil:
			withExample = carriesExampleBlock(existing)
		case errors.Is(readErr, os.ErrNotExist):
			// absent file: no block
		default:
			log.Printf("WARN [config] cannot read %s to look for the price example, saving without it: %v", configPath, readErr)
		}
	}

	// Marshal to YAML
	data, err := marshalContext(cfg, withExample)
	if err != nil {
		return err
	}

	// Write the file
	return os.WriteFile(configPath, data, 0600)
}

// ContextExists checks whether a context configuration file exists
func ContextExists(contextName string) (bool, error) {
	if err := ValidateContextName(contextName); err != nil {
		return false, err
	}

	configPath, err := GetContextPath(contextName)
	if err != nil {
		return false, err
	}

	_, err = os.Stat(configPath)
	if os.IsNotExist(err) {
		return false, nil
	}
	if err != nil {
		return false, err
	}

	return true, nil
}

// GetContextPath returns the file path for a context
// "default" -> ~/.devdesk/config.yaml
// "dev" -> ~/.devdesk/config-dev.yaml
func GetContextPath(contextName string) (string, error) {
